import{_ as s,O as a,o as i,c as o,a as r,i as n,f as l}from"./chunks/framework.fmIt2z2h.js";const m=JSON.parse('{"title":"D.04　系统、控制、反馈、韧性与时滞","description":"","frontmatter":{"title":"D.04　系统、控制、反馈、韧性与时滞","xkChars":741,"xkLessons":{"D.04":{"title":"D.04　系统、控制、反馈、韧性与时滞","lead":"知道系统画成什么网络，不等于知道它怎样响应；知道每件事单独能做，也不等于能同时做完。系统分析要把可观察、可达、资源、时限与权限放到同一个实际任务里。","explanation":["原文定位：第4577—4592行；原文锚点 section-d-04；短引文：‘调查、调度和反馈应服务于实际可执行的策略。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","系统表示把库存、流量、反馈、延迟、约束和边界接到具体对象。库存是某时点积累量，流量是单位时间进入离开的变化，反馈是返回作用影响后续状态，延迟是通道或响应需要的时间，约束限制可选动作，边界说明分析包含什么。变量和单位需与实际任务相称，不能只画箭头便说机制已证。","反馈只要求返回对后续状态有作用，不保证反馈信息真实、及时或有益。虚假指标可以导致后续错误分配，也构成返回作用；收到正确反馈却不改变后续状态，则还不能据此认定相应反馈闭环接通。组织学会一种做法、出现涌现模式、当前表示不足、跨尺度因果成立是四种不同判断：不能把难预测的模式一律称为学习，也不能把表示失败自动升级为更高层因果。","可观测性必须相对于目标。在线性观测O与目标L下，只要任何不可观察差异都不改变目标，即ker(O)⊆ker(L)，就能由观测辨认Lx，不必重建所有状态。公开理由是：若Ox=Ox′，则O(x−x′)=0；包含关系使L(x−x′)=0，故Lx=Lx′。反向若存在v满足Ov=0却Lv≠0，则x与x+v观测相同、目标不同，目标不可由该观测唯一辨认。这个结论建立在线性及给定状态域等假设下，现实映射还需核。","可控矩阵的秩只说明理想模型的某种可达性质，实际执行还受时间、输入幅度、资源、动作合法性和权限约束。即使一维系统的控制方向覆盖整个状态空间，只有一个时间步且输入上限为1，也无法从0到2。秩与行动资格不是同一层，不能把数学允许的无限输入当作现实可用资源。","同一张网络图加不同响应规则，可产生不同传播。节点可能按一次接触就改变，也可能需要多个邻居、特定顺序或足够资源。延迟遇到截止期、遗忘与耗尽可能终止传播；在无限等待、单调累积且无遗忘等特殊模型中，有限延迟可能只改变到达时间而不改变最终覆盖。两种结果不能互相普遍化，需先说明动力规则和观察终点。","韧性说明某种关系或功能在扰动中维持或恢复，但被维持的对象可能是不公制度。不能从维持成功直接推出正当，也不能把恢复原状设为每个当事人的生活目标。有时人希望退出旧结构或改变分配，而不只是恢复它；功能、价值、权利与行动选择仍需分别说明。","库存模型帮助区分暂时流量平衡与可持续容量。积压减少可能来自需求减少、能力增加、统计口径变化或外包；仅看曲线不能区分。暂时靠透支人力提高处理量，也不证明长期容量增加。短期过冲可能与多种延迟、响应强度或外扰相容，不能由一条曲线直接识别全部时滞。","历史充分写入当前状态时，仍可能有一般适应和学习，也可能符合载体型反馈介导学习；历史增量型学习则另问在指定当前表示之外，历史是否增加信息或能力。不能因为没有额外历史增量就宣布没有任何学习，也不能把一项行为改变自动登记为全部正式学习合同通过。","联合可行比各自可行更强。两个同一期到期、各需一单位容量的任务，在同期总容量只有一时分别能做，却不能同时完成。需增加真实可用容量或合法改变时序，不能在纸面上把同一资源重复分配。更进一步，相同观测若对应多个状态，每个状态各有一个正确动作，也不保证存在不知道真实状态时都可用的共同动作；可执行策略必须依赖实际能得到的信息。","十二个专题覆盖系统表示、控制反馈、观察者影响、复杂适应与涌现、网络级联、韧性、历史锁定、组织生态、观测盲区、干预能力、调节器与内部模型、库存时滞过冲。所列贝塔朗菲、梅多斯、维纳、阿什比、Holling、Arthur等是研究导航，不表明他们承诺完全一致，也不意味着本节复原了全部原作证明。最强反方认为现实限制让形式分析无用；形式分析仍能排除不可能推理和明确要补的条件，只是不能越过其模型边界充当现实授权。"],"distinctions":[{"leftTitle":"反馈","leftText":"返回作用影响后续状态。","rightTitle":"有益反馈或学习","rightText":"真假、时效、效果及学习合同都须另核。"},{"leftTitle":"目标可辨认","leftText":"观测足以决定任务所问Lx。","rightTitle":"全状态可重建","rightText":"要求更强，目标无关方向可不必观测。"},{"leftTitle":"理想可控","leftText":"在模型规定输入和时间假设下可达。","rightTitle":"现实可执行","rightText":"还需上限、资源、权限、时窗与停止补救。"},{"leftTitle":"分别可行","leftText":"各任务单独满足资源条件。","rightTitle":"联合可行","rightText":"同时竞争资源时整体仍满足约束。"},{"leftTitle":"韧性","leftText":"某种功能或关系维持。","rightTitle":"正当与值得恢复","rightText":"需规范理由及受影响者处境，不能从稳定性推出。"}],"boundaries":["ker(O)⊆ker(L)是线性目标辨认条件，不把任意非线性或现实对象直接纳入。","延迟不改变最终覆盖只在明确无限等待、单调累积、无遗忘等条件下成立。","库存和过冲曲线不能单独识别实际通道；资源转移与透支须核。","每状态各有正确动作不代表同一观测下存在共同可用策略。","本讲所有数学例是条件构造，未运行真实控制系统或复现历史航天试验。"],"questions":["O=(1,0)看不见x2，能否算2x1？","为何满秩例一步到不了2？","积压下降说明能力增加了吗？","何时延迟不改变最终覆盖？","韧性强是否证明制度应继续？"],"diagramPath":"/reading-assets/S-D-04/figures/section-d-04.png","caseLinks":[{"title":"真实原始试验记录：Apollo13应急过滤改装受材料与时间约束","href":"https://ntrs.nasa.gov/api/citations/19720021432/downloads/19720021432.pdf"}],"caseNotes":[{"title":"真实原始试验记录：Apollo13应急过滤改装受材料与时间约束","text":"NASA报告CSD-A-1066说明，Apollo13飞行期间的应急改装必须可工作、使用机组现有材料、易于清楚传达，且评估要早到足以准备替代方案。报告记载无人舱试验以注入二氧化碳模拟机组代谢；第二阶段用于确定滤罐更换时间，以减少为此依赖遥测的耗电。这把实际材料、可传达操作、时限、观测与电力约束放到同一任务。","sourceLabel":"NASA CSD-A-1066原始地面试验报告，记录1970年4月试验","sourceUrl":"https://ntrs.nasa.gov/api/citations/19720021432/downloads/19720021432.pdf","sourceLocator":"印刷p3 Objective及Discussion首段；p4首段末句、最后一段（第二阶段1970-04-16）；p5 Conclusions；PDF第6—8页原扫描","boundary":"只核报告这三页正文并目视扫描，不声称重做试验、审完附录数据或证明航天系统全部风险解决；不用报告数值指导现实生命保障操作。","href":"https://ntrs.nasa.gov/api/citations/19720021432/downloads/19720021432.pdf"}],"sourceRefs":[{"section":"D.04","start_line":4577,"end_line":4592,"startLine":4577,"endLine":4592}],"outputId":"section-d-04","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["先把系统变量、流量单位、边界和响应规则接到具体任务。","按目标检验观测能否区分必要状态，不要求无关的全状态重建。","将理想可达性与实际时限、输入上限、资源和权限分开核。","检查动力规则、延迟与终点，再解释传播、库存和韧性，避免从图形推断机制。","核联合资源约束与同观测下的共同策略，调查和调度服务真实可执行性。"],"teachingExamples":[{"title":"数学教学构造：不必看见全部状态","text":"设x=(x1,x2)，观测O=(1,0)，目标L=(2,0)。不可见方向为(0,t)，也全部不改变L，故观测z=x1足以得到目标2z，而x2仍未知。若目标改L′=(0,1)，同观测的(0,0)与(0,1)有不同目标，便不能辨认。","assumptions":"状态空间为R²，观测和目标线性且无噪声。","boundary":"真实测量误差和目标定义须另核，不能据例忽略关键状态。"},{"title":"数学教学构造：秩满也可能来不及","text":"一维x下一步=x+u，控制矩阵为[1]、秩1；从0到目标2若只有一步且|u|≤1，则可达区间[−1,1]，不能到2。若允许两步且每步u=1，形式上可以到2，但现实权限与资源仍未由此证明。","assumptions":"确定性离散模型，无外扰，时间步和幅度上限明确。","boundary":"不估计任何真实设备能力。"},{"title":"数学教学构造：联合任务与隐藏状态","text":"两个同期截止任务各需容量1，总容量1，单项各可行而合计需2>1；容量增至2或合法错开时窗才改变条件。另设状态A只能用动作a成功、状态B只能用b成功，但两状态观测相同且a≠b，无新增信息时没有同时对两者正确的单一动作。","assumptions":"动作集和成功条件均为教学构造；后一例允许动作只有a和b。","boundary":"现实可另研究安全暂停或调查，但不能凭空假设它们无成本或总可行。"},{"title":"数学教学构造：相同连线，不同延迟结局","text":"设仅A→B一条边，事件从时点0由A发出、延迟2到B。若B必须在时点1前收到，传播失败；若允许无限等待且到达即永久激活，则时点2激活，最终覆盖仍为A、B。","assumptions":"有限正延迟、没有遗忘、耗尽或其他边；两种情境仅截止条件不同。","boundary":"没有据此断言现实所有延迟只影响速度或必定终止。"}],"counterexamples":[{"identity":"constructed_boundary","text":"反馈回来了，所以系统一定学会正确做法。","effect":"返回作用、真实性、有益性与学习分别取证。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"控制矩阵满秩，就有权立即完成目标动作。","effect":"秩不提供时限资源或现实授权，幅度受限例已反证。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"每个状态都存在正确动作，因此在任何信息条件下都能正确行动。","effect":"信息不可分时可行动作交集可能为空。","sourceIds":["theory"]}],"questionAnswers":[{"question":"O=(1,0)看不见x2，能否算2x1？","answer":"能，因为不可见方向不改变目标；无需重建无关的x2。","basis":"本节原文及上述公开推导"},{"question":"为何满秩例一步到不了2？","answer":"现实化的输入上限只允许一步增减1，形式方向覆盖不代表任意幅度可用。","basis":"本节原文及上述公开推导"},{"question":"积压下降说明能力增加了吗？","answer":"未必，需求、外包或统计边界变化也可造成，需通道材料。","basis":"本节原文及上述公开推导"},{"question":"何时延迟不改变最终覆盖？","answer":"仅在具体模型允许无限等待、单调累积无遗忘等相关条件满足时，且所有必要到达仍发生。","basis":"本节原文及上述公开推导"},{"question":"韧性强是否证明制度应继续？","answer":"不证明；功能维持和规范正当要分别判断。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-04/figures/section-d-04.png","alt":"任务与表示，库存／流量／反馈，延迟／约束／边界；目标可观测，ker(O) ⊆ ker(L)，不必重建全部状态；理想可控另核，时限／幅度／资源，权限／实际可达；图相同≠动力相同，响应规则决定传播，延迟条件须说明；单项可行≠联合可行，同观测可能无共同动作；反馈≠有益或学习，韧性≠规范正当。作者依D.04绘制；条件形式例不认证真实设备或组织的控制能力。","caption":"作者依D.04绘制；条件形式例不认证真实设备或组织的控制能力。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换目标L、输入上限、任务截止和观测区分能力，分别显示形式辨认与策略可行条件。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"原始地面试验报告显示可用材料、时间与资源怎样限制执行方案；不把一次应急成功当作所有反馈或韧性的证明。"},"openQuestions":["未取得04.01—04.12全部研究原稿，不复原其全部理论推导与历史采纳。"],"taskId":"S-D-04","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4577—4592行；每节精确范围见sourceRefs","claim_support":["D.04：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"apollo13-lioh","title":"CSD-A-1066 Final Report – Apollo 13 LiOH Canister Test","url":"https://ntrs.nasa.gov/api/citations/19720021432/downloads/19720021432.pdf","source_type":"primary","version_or_date":"CSD-A-1066；记述1970-04-14及04-16试验，NTRS归档号19720021432","locator":"印刷pp3—5；Objective、Discussion首段与p4第二阶段段、Conclusions；PDF第6—8页已目视原扫描","claim_support":["改装需可工作、现有材料、易于传达及及时评估；无人舱模拟；试验确定更换间隔以减少遥测耗电"],"limits":["只核三页报告正文，不重做试验、不使用附录曲线或未核全文数值作结论。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-04/lecture.md","sourcesPath":"/reading-assets/S-D-04/sources.json","sourceSlicePath":"/reading-assets/S-D-04/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-04/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-04.md","filePath":"theory/appendix-d/d-04.md"}'),d={name:"theory/appendix-d/d-04.md"};function c(p,e,u,x,h,f){const t=a("SectionLesson");return i(),o("div",null,[e[0]||(e[0]=r('<div class="theory-source"><h1 id="section-d-04" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.04</span><span class="xk-num__gap">　</span></span>系统、控制、反馈、韧性与时滞 <a class="header-anchor" href="#section-d-04" aria-label="Permalink to &quot;D.04　系统、控制、反馈、韧性与时滞 {#section-d-04}&quot;">​</a></h1><p>正文连接：§3.3；§4.5—4.6；§5.5；§6；§12.6。研究入口：04.01—04.12。</p><p>系统表示的价值在于把库存、流量、反馈、延迟、约束与边界接到具体对象上。反馈只要求返回对后续状态有作用，不保证信息真实、回应及时或结果有益。组织学会了一种做法、系统出现涌现模式、当前表示不足和跨尺度因果成立，是四种需另证的判断。</p><p>可观测性和可控性必须相对于任务。线性例中，若观测算子为O、目标量为Lx，辨认目标只需要不可观察方向不改变目标，即ker(O)包含的方向均在ker(L)内，不一定需要重建全部状态。控制矩阵的秩可说明理想模型中的可达性质，却不保证在真实时限、输入上限、资源和权限下可以执行。</p><p>同一张网络图配上不同响应规则，会产生不同传播。延迟可使具有截止期、遗忘或资源耗尽的过程停止；在无限等待、单调累积且无遗忘的特殊模型中，延迟未必改变最终覆盖。韧性描述某种关系或功能维持，不自动说明被维持的制度正当，也不将恢复原状设为唯一生活目标。</p><p>库存教学模型有助于区分暂时流量平衡与可持续容量。看见积压下降，仍要问需求下降、处理能力提升、统计边界改变或任务外包哪条通道发生；看见短期过冲，也不能仅凭曲线识别全部时滞。历史充分写入当前状态时，一般适应与学习仍可存在，载体型反馈介导学习与历史增量型学习分别判断。</p><p>行动能力还需要从单项可行走向联合可行。两个各需一单位容量、在同一期截止的任务，可以分别做得到，却不能由同期总容量一共同完成；增加容量或合法错开截止才会改变可行性。相同观测对应多个状态时，每个状态分别有正确动作，也不保证在看不见状态区别时有共同可用的动作。调查、调度和反馈应服务于实际可执行的策略。</p><p>专题定位：04.01 一般系统论与系统思维：贝塔朗菲、梅多斯；04.02 控制论：维纳、阿什比；04.03 二阶控制论与观察者反身性；04.04 复杂适应系统与涌现；04.05 网络耦合、级联与非线性；04.06 韧性与适应循环：Holling 等；04.07 路径依赖、锁定与滞后：Arthur 等；04.08 组织生态与系统生命周期；04.09 可观测性与测量盲区；04.10 可控性与真实干预能力；04.11 好调节器定理与内部模型；04.12 系统动力学、库存、时滞与过冲。</p></div>',1)),n(t,{section:"D.04"}),e[1]||(e[1]=l("div",{class:"theory-source"},null,-1))])}const g=s(d,[["render",c]]);export{m as __pageData,g as default};
